select u.user_id, u.dept_id, u.nick_name, u.user_name, u.user_type, u.email, u.avatar, u.phonenumber, u.sex, u.status, u.del_flag, u.login_ip, u.login_date, u.create_by, u.create_time, u.remark from sys_user u
where u.del_flag = '0'

	AND u.user_id = #{user.userId}


	AND u.user_name like concat('%', #{user.userName}, '%')


	AND u.nick_name like concat('%', #{user.nickName}, '%')


	AND u.status = #{user.status}


	AND u.user_type = #{user.userType}


	AND u.phonenumber like concat('%', #{user.phonenumber}, '%')


	AND date_format(u.create_time,'%Y%m%d') >= date_format(#{beginTime},'%Y%m%d')


	AND date_format(u.create_time,'%Y%m%d') <= date_format(#{endTime},'%Y%m%d')


	AND u.dept_id IN

		#{deptId}

